#[tokio::test]
async fn cancelling_a_partial_search_frame_shuts_down_the_shared_socket() {
    let fixture = Store::new();
    let events = broadcast::channel(2).0;
    let access = share_request::Access::new(&fixture.authority, &fixture.shares, &events);
    let (server, mut peer) = tokio::net::UnixStream::pair().expect("pair");
    let server = server.into_std().expect("std socket");
    let socket = Arc::new(server.try_clone().expect("shutdown handle"));
    let (_, write) = tokio::net::UnixStream::from_std(server)
        .expect("async socket")
        .into_split();
    let write: Box<dyn tokio::io::AsyncWrite + Unpin + Send> = Box::new(write);
    let wire = Arc::new(Mutex::new(AsyncWireWriter::new(write)));
    let writer = Writer {
        wire: wire.clone(),
        socket: Some(socket),
        stream_id: 1,
        access: &access,
    };
    let payload = "x".repeat(8 * 1024 * 1024);
    let mut send = Box::pin(writer.send(FrameKind::SearchPage, 1, &payload));
    tokio::time::timeout(Duration::from_secs(2), async {
        tokio::select! {
            result = &mut send => panic!("large write should be backpressured: {result:?}"),
            result = peer.readable() => result.expect("partial bytes"),
        }
    })
    .await
    .expect("write starts");
    drop(send); // Simulates cancelling just this search task, not the connection.
    let mut partial = vec![];
    tokio::time::timeout(Duration::from_secs(1), peer.read_to_end(&mut partial))
        .await
        .expect("shutdown despite other writer owners")
        .expect("partial read");
    assert!(!partial.is_empty());
    assert!(partial.len() < payload.len());
    assert!(
        writer
            .send(FrameKind::Response, 0, &"must not follow partial frame")
            .await
            .is_err()
    );
}

#[tokio::test]
async fn search_writer_rechecks_revocation_after_waiting_for_the_writer() {
    let fixture = Store::new();
    let events = broadcast::channel(2).0;
    let access = share_request::Access::new(&fixture.authority, &fixture.shares, &events);
    let (server, peer) = tokio::net::UnixStream::pair().expect("pair");
    let server = server.into_std().expect("std socket");
    let socket = Arc::new(server.try_clone().expect("shutdown handle"));
    let (_, write) = tokio::net::UnixStream::from_std(server)
        .expect("async socket")
        .into_split();
    let write: Box<dyn tokio::io::AsyncWrite + Unpin + Send> = Box::new(write);
    let wire = Arc::new(Mutex::new(AsyncWireWriter::new(write)));
    let writer = Writer {
        wire: wire.clone(),
        socket: Some(socket),
        stream_id: 1,
        access: &access,
    };
    let held = wire.lock().await;
    let mut send = Box::pin(writer.send(FrameKind::SearchPage, 1, &"sensitive"));
    assert!(
        std::future::poll_fn(|cx| std::task::Poll::Ready(send.as_mut().poll(cx)))
            .await
            .is_pending()
    );
    fixture
        .shares
        .lock()
        .await
        .revoke(fixture.authority.identity().expect("share ID"))
        .expect("durable revocation without event");
    drop(held);
    assert!(send.await.is_err());
    assert_eq!(
        peer.try_read(&mut [0])
            .expect_err("no bytes admitted")
            .kind(),
        std::io::ErrorKind::WouldBlock
    );
}

use super::*;
use std::{
    fs::{self, DirBuilder},
    os::unix::{fs::DirBuilderExt, net::UnixListener},
    path::PathBuf,
    sync::{Arc, Mutex},
    thread::{self, JoinHandle},
    time::Duration,
};
use superplexr_core::{MissionId, RunId};
use superplexr_protocol::{
    ClientRequest, Request, ResponseBody, ServerResponse, ShareRole, ShareSummary,
    wire_v3::{FrameKind, SyncWire},
};

/// The real native client connects and negotiates capabilities. The peer records
/// all non-handshake requests and rejects them promptly, so an accidental RPC
/// cannot masquerade as an argument-validation failure or hang for its timeout.
struct NativeFixture {
    backend: Option<ControlBackend>,
    calls: Arc<Mutex<Vec<Request>>>,
    peer: Option<JoinHandle<()>>,
    directory: PathBuf,
}

impl NativeFixture {
    fn new(terminal_read: bool, workflow_read: bool, shared: bool) -> Self {
        let directory =
            std::env::temp_dir().join(format!("um-{}", MissionId::new().as_uuid().simple()));
        DirBuilder::new().mode(0o700).create(&directory).unwrap();
        let socket = directory.join("s");
        let listener = UnixListener::bind(&socket).unwrap();
        let calls = Arc::new(Mutex::new(Vec::new()));
        let recorded = calls.clone();
        let peer = thread::spawn(move || {
            let (stream, _) = listener.accept().unwrap();
            stream
                .set_read_timeout(Some(Duration::from_secs(10)))
                .unwrap();
            stream
                .set_write_timeout(Some(Duration::from_secs(10)))
                .unwrap();
            let mut wire = SyncWire::new(stream);
            wire.server_handshake(MissionId::new().as_uuid()).unwrap();
            while let Ok(request) = wire.receive_json::<ClientRequest>(FrameKind::Request, 0) {
                let response = match request.action {
                    Request::Ping => {
                        ServerResponse::success(request.request_id, ResponseBody::Pong)
                    }
                    Request::ShareIdentity if shared => ServerResponse::success(
                        request.request_id,
                        ResponseBody::ShareIdentity {
                            share: ShareSummary {
                                share_id: MissionId::new().as_uuid(),
                                label: "inspection fixture".into(),
                                role: ShareRole::Observer,
                                mission_ids: vec![],
                                session_ids: vec![],
                                created_at_micros: 1,
                                expires_at_micros: u64::MAX,
                                revoked_at_micros: None,
                            },
                        },
                    ),
                    action => {
                        recorded.lock().unwrap().push(action);
                        ServerResponse::error(
                            request.request_id,
                            "fixture_rpc",
                            "native RPC reached",
                        )
                    }
                };
                if wire.send_json(FrameKind::Response, 0, &response).is_err() {
                    break;
                }
            }
        });
        let client = if shared {
            ControlClient::connect_with_share(&socket, "fixture-share")
        } else {
            ControlClient::connect(&socket)
        }
        .unwrap();
        Self {
            backend: Some(ControlBackend {
                client,
                read_only: shared,
                terminal_read,
                workflow_read,
            }),
            calls,
            peer: Some(peer),
            directory,
        }
    }

    fn backend(&self) -> &ControlBackend {
        self.backend.as_ref().unwrap()
    }

    fn request(&self, method: &str, params: Value) -> Value {
        let line = json!({"jsonrpc":"2.0","id":1,"method":method,"params":params});
        serde_json::from_str(&handle_line(self.backend(), &line.to_string()).unwrap()).unwrap()
    }

    fn call(&self, name: &str, arguments: Value) -> Value {
        self.request("tools/call", json!({"name":name,"arguments":arguments}))
    }

    fn no_calls(&self) {
        assert!(
            self.calls.lock().unwrap().is_empty(),
            "unexpected native RPC"
        );
    }
}

impl Drop for NativeFixture {
    fn drop(&mut self) {
        self.backend.take();
        if let Some(peer) = self.peer.take() {
            let _ = peer.join();
        }
        let _ = fs::remove_dir_all(&self.directory);
    }
}

fn error_text(response: &Value) -> &str {
    assert_eq!(response["result"]["isError"], true, "{response}");
    response["result"]["content"][0]["text"].as_str().unwrap()
}

#[test]
fn share_token_argument_requires_either_explicit_inspection_module() {
    for args in [
        vec!["superplexr-mcp", "--share-token-file", "/private/token"],
        vec![
            "superplexr-mcp",
            "--read-only",
            "--share-token-file",
            "/private/token",
        ],
    ] {
        let error = Args::try_parse_from(args).unwrap_err();
        assert_eq!(
            error.kind(),
            clap::error::ErrorKind::MissingRequiredArgument
        );
    }
    for (terminal, workflow) in [(true, false), (false, true), (true, true)] {
        let mut argv = vec!["superplexr-mcp", "--share-token-file", "/private/token"];
        if terminal {
            argv.push("--terminal-read");
        }
        if workflow {
            argv.push("--workflow-read");
        }
        let args = Args::try_parse_from(argv).unwrap();
        assert_eq!(
            (args.terminal_read, args.workflow_read),
            (terminal, workflow)
        );
        assert_eq!(
            args.share_token_file.as_deref(),
            Some(std::path::Path::new("/private/token"))
        );
    }
    let defaults = Args::try_parse_from(["superplexr-mcp"]).unwrap();
    assert!(!defaults.terminal_read && !defaults.workflow_read);
}

#[test]
fn inspection_modules_are_independent_and_disabled_tools_reject_direct_calls() {
    for shared in [false, true] {
        for (terminal, workflow) in [(false, false), (true, false), (false, true), (true, true)] {
            let fixture = NativeFixture::new(terminal, workflow, shared);
            let listed = fixture.request("tools/list", json!({}));
            let names: Vec<_> = listed["result"]["tools"]
                .as_array()
                .unwrap()
                .iter()
                .map(|tool| tool["name"].as_str().unwrap())
                .collect();
            for name in ["verification_list", "verification_status"] {
                assert_eq!(names.contains(&name), workflow);
                if !workflow {
                    assert!(error_text(&fixture.call(name, json!({}))).contains("--workflow-read"));
                }
            }
            for name in ["terminal_list", "terminal_capture", "terminal_history"] {
                assert_eq!(names.contains(&name), terminal);
                if !terminal {
                    assert!(error_text(&fixture.call(name, json!({}))).contains("--terminal-read"));
                }
            }
            assert_eq!(names.contains(&"fault_list"), !shared);
            if shared {
                for name in [
                    "fault_list",
                    "fault_show",
                    "fault_repro",
                    "fault_guard",
                    "fault_resolve",
                    "fault_dismiss",
                    "fault_report",
                ] {
                    assert!(!names.contains(&name));
                    assert!(error_text(&fixture.call(name, json!({}))).contains("Share-connected"));
                }
            }
            fixture.no_calls();
        }
    }
}

